#!/usr/bin/env python3
"""Render grouped instrument status; no object decisions are read or written."""
import csv
from pathlib import Path
import argparse
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('tables',type=Path)
parser.add_argument('output',type=Path,help='New status TSV; must not exist')
args=parser.parse_args()
R=args.tables
recorded = ['A02', 'A05', 'A08', 'A10', 'A12', 'A14', 'A15', 'M02', 'M04', 'M06', 'M08', 'M10', 'M12', 'M13', 'V01', 'V04', 'V06', 'V08']
partial = ['A01', 'A06', 'A13', 'G01', 'M01', 'M07', 'M09', 'T01', 'T02', 'T04', 'T06', 'V05']
notes = {'A01': '41 cache-reference records; no per-object acquisition-event record is emitted by extra_alma.py/extra_void.py.', 'A02': 'Current file content and sanitized installer/network directives recorded.', 'A03': 'Recipe, bounded retained-history extracts and scriptlets recorded; no complete per-object choice/change event table is emitted.', 'A04': 'Current unit/preset and bounded operation extracts recorded; no original per-unit disablement-event record is emitted.', 'A05': 'Three inner-store metadata scans completed; zero nested atomic boundaries in the scan counters.', 'A06': 'Inner metadata and prefixes recorded; no complete per-member payload receipt or creation-event table is emitted.', 'A07': 'Current key metadata and DNF history recorded; no per-key import-reason field is emitted.', 'A08': 'Selected ALSA file contents recorded in alma-facts.tsv.', 'A09': 'Stored values and bounded history extracts recorded; no per-value creation-event record is emitted.', 'A10': 'Native semanage query records persistent boolean values.', 'A11': 'Values, script and bounded history extracts recorded; no per-value chooser-event record is emitted.', 'A12': 'Five isolated dconf database reads succeeded.', 'A13': 'Schemas/profiles and bounded current mapped-reader snapshot recorded; no complete consumer history is emitted.', 'A14': '24 cache queries decoded with native package-file joins; 2 dependent IDs are outside the fixed matching inputs.', 'A15': '41 verified cache-reference archives and 459 equal complete member comparisons recorded; reference type is retained.', 'V01': '41 lock-addressed verified archives and 459 equal complete member comparisons recorded; directory entries are separately labeled.', 'V02': 'Installed/residual/cache manifest routes yield zero unowned members with a reference; 6859 paths have no-surviving-receipt; 22282 equal comparisons belong to already-owned paths.', 'V03': 'Current sources and package records retained; no per-account/group/sudo installation-choice event table is emitted.', 'V04': 'Three inner-store scans completed with zero nested atomic boundaries; parent association documented.', 'V05': 'Metadata and prefixes recorded; no complete per-member payload receipt or creation-event table is emitted.', 'V06': 'Selected configuration bytes and whole-file hashes recorded.', 'V07': 'Current text/key/mount records retained; historical_creator remains an unknown marker, no creation-event record emitted.', 'V08': 'Font-cache source paths and native package-file joins recorded; 1 dependent ID is outside the fixed matching inputs.', 'M01': 'Sysusers files and RPM scriptlets recorded; no per-account/group creation-event table is emitted.', 'M02': '263 of 263 unit selections recorded with source files and enablement links.', 'M03': 'Current links and script text recorded; no per-link enablement-event table is emitted.', 'M04': 'Sudo source bytes and native package-file comparisons recorded; 8 dependent IDs, 7 duplicate old-key IDs, at most 1 structural match.', 'M05': 'Source bytes and comparisons recorded; no per-rule choice-event table is emitted; 7 dependent IDs, 6 duplicate old-key IDs, at most 1 structural match.', 'M06': '2219 active /etc descendants traversed; snapshot marker retained.', 'M07': 'Two snapshot-root manifests and 15837 complete comparisons recorded; no reference for every snapshot member is emitted.', 'M08': '16177 of 16177 snapshot/current file pairs have complete SHA256 comparisons.', 'M09': 'Two SELinux store listings/checksums and snapshot/current comparisons recorded; no original per-copy receipt or derivation-event record is emitted.', 'M10': 'Complete bounded grubenv bytes recorded.', 'M11': 'Current boot values recorded; no per-value creation/choice event table is emitted.', 'M12': 'Snapshot-root package set and database-file comparisons recorded; 1 dependent ID is outside the fixed matching inputs.', 'M13': 'One solver-cache decode and three cache/source files recorded; 1 dependent ID is outside the fixed matching inputs.', 'T01': 'Three current StaticPod image references recorded; no historical pull-actor table is emitted.', 'T02': 'Six opaque roots expanded; 18 component boundaries remain after three listing methods.', 'T03': 'Current listing/hash/mount queries emit no original complete installed-image member manifest or receipt comparison.', 'T04': 'API-daemon mountinfo recorded; no per-object historical overlay-layer record is emitted.', 'T05': 'Current listing/content/source references recorded; no per-member creation/derivation-event table is emitted.', 'T06': '5940 of 5963 initial regular files have complete hashes; 23 remain not-found after Read, Copy and fresh-metadata Read (9 containerd, 14 kubelet).', 'G01': 'Fresh four-slot boot and two-level inventory recorded; browser_extension and container_run each exit 1; full prescribed action sequence did not succeed.', 'V09': 'No per-trust-value historical choice or complete consumer/use record is emitted by the existing collector; 0 matching-input IDs. No new probe attempted.', 'M14': 'No per-trust-value historical choice or complete consumer/use record is emitted by the existing collector; 0 matching-input IDs. No new probe attempted.'}
evidence = {'alma': 'S4/rehearsal/alma/round3', 'void': 'S4/rehearsal/void/round3', 'microos': 'S4/rehearsal/microos/round-3', 'talos': 'S4/rehearsal/talos/content-final', 'gentoo': 'S4/rehearsal/gentoo/round2'}
rows = list(csv.DictReader((R / 'MISSING.tsv').open(), delimiter='\t'))
assert {r['fact'].split(':')[0] for r in rows} == set(notes)
with args.output.open('x', newline='') as f:
    w = csv.writer(f, delimiter='\t', lineterminator='\n')
    w.writerow(['machine', 'fact_id', 'status', 'evidence', 'reason_or_limit'])
    for r in rows:
        key = r['fact'].split(':')[0]
        status = 'recordable' if key in recorded else 'partial' if key in partial else 'not-obtainable'
        w.writerow([r['machine'], key, status, evidence[r['machine']] + ';S4/collector/extra_' + r['machine'] + '.py' if r['machine'] != 'gentoo' else evidence[r['machine']], notes[key]])
print(f'{len(recorded)} of {len(rows)} fact groups recordable; {len(partial)} partial; {len(rows) - len(recorded) - len(partial)} not obtainable')
